const webhookData = $node['Email Webhook Trigger'].json;
const emailBody = webhookData.body.body;
const emailFrom = webhookData.body.from;
const emailSubject = webhookData.body.subject;

const urlMatch = emailBody.match(/https?:\/\/[^\s]+/);
const reportUrl = urlMatch ? urlMatch[0] : null;

if (!reportUrl) {
  throw new Error('No report URL found in email');
}

return {
  reportUrl: reportUrl,
  emailFrom: emailFrom,
  emailSubject: emailSubject,
  timestamp: new Date().toISOString()
};

const payload = {
  url: $node['Extract Report URL'].json.reportUrl
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://playwright-scraper:8002/api/v1/scrape',
  headers: {
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

return response;

// Extract content from scraper response
const scraperResponse = $node['Scrape Report'].json || {};

// Try to extract content from various possible locations
let scrapedContent = '';

// First check if there's a nested json object
if (scraperResponse.json) {
  scrapedContent = typeof scraperResponse.json === 'string' ? 
                   scraperResponse.json : 
                   JSON.stringify(scraperResponse.json);
}

// Otherwise try data field
if (!scrapedContent && scraperResponse.data) {
  scrapedContent = typeof scraperResponse.data === 'string' ? 
                   scraperResponse.data : 
                   JSON.stringify(scraperResponse.data);
}

// Try other common field names
if (!scrapedContent) {
  scrapedContent = scraperResponse.html_content || 
                   scraperResponse.text_content || 
                   scraperResponse.content || 
                   scraperResponse.body || 
                   scraperResponse.text || 
                   scraperResponse.binary || '';
}

if (!scrapedContent) {
  const fields = Object.keys(scraperResponse).join(', ');
  const preview = JSON.stringify(scraperResponse).substring(0, 300);
  throw new Error(`No content found. Available fields: ${fields}. Sample: ${preview}`);
}

const payload = {
  report_id: $node['Extract Report URL'].json.reportUrl,
  raw_extracted_text: scrapedContent.trim(),
  prompt_type: 'default'
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://ai-analyzer:8000/api/v1/analyze',
  headers: {
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

return response;

// Check if analysis was successful
const analyzeOutput = $node['Analyze Report'].json;
const hasAnalysis = analyzeOutput?.raw_analysis && 
                    analyzeOutput.analysis_response !== null && 
                    analyzeOutput.analysis_response !== '';

return {
  success: hasAnalysis,
  raw_analysis: analyzeOutput?.raw_analysis || null,
  report_id: analyzeOutput?.report_id || null,
  api_provider: analyzeOutput?.api_provider || null
};

const analysis = $node['Analyze Report'].json;
const emailFrom = $node['Extract Report URL'].json.emailFrom;

if (!emailFrom) {
  throw new Error('Email address not provided in webhook');
}

if (!analysis.analysis_id) {
  throw new Error('Analysis ID not returned from AI analyzer service');
}

const payload = {
  analysis_id: analysis.analysis_id,
  report_id: analysis.report_id || 'unknown',
  channels: ['email'],
  recipients: {
    email: String(emailFrom).trim().toLowerCase()
  },
  message_type: 'summary'
};

console.log('Send Email payload:', JSON.stringify(payload));

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://notification-service:8004/api/v1/notify',
  headers: {
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

return response;

const analysis = $node['Analyze Report'].json;
const telegramChatId = $env.TELEGRAM_CHAT_ID;

if (!telegramChatId) {
  throw new Error('TELEGRAM_CHAT_ID environment variable not set');
}

if (!analysis.analysis_id) {
  throw new Error('Analysis ID not returned from AI analyzer service');
}

const payload = {
  analysis_id: analysis.analysis_id,
  report_id: analysis.report_id || 'unknown',
  channels: ['telegram'],
  recipients: {
    telegram: String(telegramChatId).trim()
  },
  message_type: 'summary'
};

console.log('Send Telegram payload:', JSON.stringify(payload));

const httpResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://notification-service:8004/api/v1/notify',
  headers: {
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

return httpResponse;

const reportUrl = $node['Extract Report URL'].json.reportUrl;
const emailFrom = $node['Extract Report URL'].json.emailFrom;
const telegramChatId = $env.TELEGRAM_CHAT_ID;

if (!telegramChatId) {
  throw new Error('TELEGRAM_CHAT_ID environment variable not set');
}

// For failure alerts, use a generated UUID-like ID from the report URL
const crypto = require('crypto');
const analysisId = crypto.createHash('sha256').update(reportUrl).digest('hex').substring(0, 32);

const payload = {
  analysis_id: analysisId,
  report_id: reportUrl || 'unknown',
  channels: ['telegram'],
  recipients: {
    telegram: String(telegramChatId).trim()
  },
  message_type: 'alert',
  context_data: {
    report_title: '⚠️ Analysis Failed',
    summary: `Failed to analyze report from ${emailFrom}. Please check the logs for more details. URL: ${reportUrl}`,
    sentiment: 'Critical',
    confidence_score: 1.0
  }
};

console.log('Send Failure Alert payload:', JSON.stringify(payload));

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://notification-service:8004/api/v1/notify',
  headers: {
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

return response;

const auditEntry = {
  timestamp: new Date().toISOString(),
  emailFrom: $node['Extract Report URL'].json.emailFrom,
  reportUrl: $node['Extract Report URL'].json.reportUrl,
  analysisStatus: 'completed',
  workflowStatus: 'success'
};

return auditEntry;
